  <script>
    const filterButtons = Array.from(document.querySelectorAll('.filter-button'));
    const productCards = Array.from(document.querySelectorAll('.product-card'));
    const filterStatus = document.getElementById('filter-status');
    const addButtons = Array.from(document.querySelectorAll('.add-button'));

    function setPressedButton(activeFilter) {
      filterButtons.forEach((button) => {
        button.setAttribute('aria-pressed', String(button.dataset.filter === activeFilter));
      });
    }

    function updateProducts(activeFilter) {
      let visibleCount = 0;

      productCards.forEach((card) => {
        const matches = activeFilter === 'all' || card.dataset.category === activeFilter;
        card.hidden = !matches;
        if (matches) {
          visibleCount += 1;
        }
      });

      const label = activeFilter === 'all' ? 'featured' : activeFilter;
      filterStatus.textContent = visibleCount === 1
        ? `Showing 1 ${label} product.`
        : `Showing ${visibleCount} ${label} products.`;
    }

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const activeFilter = button.dataset.filter;
        setPressedButton(activeFilter);
        updateProducts(activeFilter);
      });
    });

    addButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const productName = button.dataset.productName;
        filterStatus.textContent = `${productName} added to cart.`;
      });
    });
