      padding: clamp(1.4rem, 2.8vw, 2.2rem);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.18em;
      font-size: 0.8rem;
      font-weight: 700;
    }

    h1,
    h2,
    h3,
    h4,
    p {
      margin-top: 0;
    }

    h1 {
      margin-bottom: 1rem;
      font-size: clamp(2.5rem, 5vw, 4.8rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 11ch;
    }

    .lead {
      color: var(--muted);
      font-size: 1.05rem;
      max-width: 60ch;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 1.6rem;
    }

    .button,
    .chip,
    .filter-button,
    .add-button {
      border: 1px solid transparent;
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      line-height: 1;
      cursor: pointer;
      transition:
        transform 0.15s ease,
        background-color 0.15s ease,
        border-color 0.15s ease,
        color 0.15s ease;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 2.9rem;
      padding: 0.85rem 1.25rem;
      text-decoration: none;
    }

    .button--primary {
      background: linear-gradient(135deg, var(--accent-strong), #85e0ff);
      color: #03101a;
      box-shadow: 0 16px 30px rgba(64, 189, 248, 0.22);
    }

    .button--secondary {
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
      border-color: var(--border-strong);
    }

    .button:hover,
    .chip:hover,
    .filter-button:hover,
    .add-button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible,
    .chip:focus-visible,
    .filter-button:focus-visible,
    .add-button:focus-visible,
    a:focus-visible,
    summary:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .hero-panel {
      padding: 1.4rem;
      display: grid;
      gap: 1rem;
      align-content: start;
    }

    .hero-panel__figure {
      margin: 0;
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--border);
      background:
        radial-gradient(circle at 20% 20%, rgba(127, 209, 255, 0.18), transparent 38%),
        linear-gradient(145deg, #112032, #08101a 70%);
    }

    .hero-panel__meta {
      display: grid;
      gap: 0.45rem;
    }

    .kicker-row,
    .product-meta,
    .deal-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      align-items: center;
    }

    .chip {
      padding: 0.45rem 0.75rem;
      border-color: var(--border);
      background: rgba(255, 255, 255, 0.04);
      color: var(--muted);
      min-height: 2.1rem;
    }

    .chip[aria-pressed="true"] {
      background: rgba(127, 209, 255, 0.16);
      border-color: rgba(127, 209, 255, 0.45);
      color: var(--text);
    }

    .status {
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 600;
    }

    .section-card {
      padding: 1.4rem;
    }

    .section-header {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.1rem;
    }

    .section-header p {
      color: var(--muted);
      max-width: 56ch;
      margin-bottom: 0;
    }

    .section-actions {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
    }

    .filter-button {
      min-height: 2.4rem;
      padding: 0.55rem 0.9rem;
      background: rgba(255, 255, 255, 0.04);
      color: var(--muted);
      border-color: var(--border);
    }

    .filter-button[aria-pressed="true"] {
      background: rgba(247, 188, 115, 0.16);
      border-color: rgba(247, 188, 115, 0.42);
      color: var(--text);
    }

    .grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(12, minmax(0, 1fr));
    }

    .products {
      grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    }

    .deals {
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    }

    .editorial {
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    }

    .product-card,
    .deal-card,
    .story-card {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.015));
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      overflow: hidden;
    }

    .product-media,
    .story-media {
      border-bottom: 1px solid var(--border);
      background: linear-gradient(145deg, rgba(127, 209, 255, 0.08), rgba(247, 188, 115, 0.03));
    }

    .product-body,
    .story-body,
    .deal-body {
      padding: 1rem;
      display: grid;
      gap: 0.8rem;
    }

    .product-card h3,
    .deal-card h3,
    .story-card h3 {
      margin-bottom: 0.35rem;
      font-size: 1.05rem;
    }

    .price {
      font-size: 1.2rem;
      font-weight: 800;
    }

    .compare {
      color: var(--muted);
      text-decoration: line-through;
    }

    .muted {
      color: var(--muted);
    }

    .rating {
      color: var(--accent-warm);
      font-weight: 700;
      letter-spacing: 0.06em;
    }

    .add-button {
      min-height: 2.7rem;
      padding: 0.75rem 1rem;
      background: rgba(127, 209, 255, 0.13);
      border-color: rgba(127, 209, 255, 0.28);
      color: var(--text);
      width: 100%;
    }

    .deal-card {
      position: relative;
    }

    .deal-badge {
      display: inline-flex;
      align-items: center;
      min-height: 1.9rem;
      padding: 0.3rem 0.65rem;
      border-radius: 999px;
      background: rgba(247, 188, 115, 0.15);
      border: 1px solid rgba(247, 188, 115, 0.35);
      color: #ffd9ad;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .story-card {
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .story-link {
      color: var(--accent);
      font-weight: 700;
      text-decoration: none;
    }

    .story-link:hover {
      color: #c6edff;
    }

    footer {
      padding: 1rem 0 2rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      padding-top: 1.25rem;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
      border: 0;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 860px) {
      .hero {
        grid-template-columns: 1fr;
      }

      .header-inner {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 600px) {
      .shell {
        width: min(100% - 1rem, var(--content-width));
      }

      main {
        gap: 2.5rem;
      }

      .hero-copy,
      .hero-panel,
      .section-card {
        border-radius: 22px;
      }

      h1 {
        font-size: clamp(2.1rem, 11vw, 3.6rem);
      }

      .section-header {
        align-items: start;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --bg-elevated: Canvas;
        --bg-panel: Canvas;
        --border: CanvasText;
        --border-strong: CanvasText;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: LinkText;
        --accent-strong: LinkText;
        --accent-warm: LinkText;
        --success: CanvasText;
      }

      body,
      header,
      .hero-copy,
      .hero-panel,
      .section-card,
      .product-card,
      .deal-card,
      .story-card {
        forced-color-adjust: auto;
        box-shadow: none;
      }

      .button,
      .chip,
      .filter-button,
      .add-button,
      .brand-mark {
        border-color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header>
    <div class="shell header-inner">
      <a class="brand" href="#" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Northstar Retail</span>
      </a>

      <nav aria-label="Primary">
        <ul>
          <li><a href="#featured-products">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Journal</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <p class="eyebrow">New season / dark edition</p>
          <h1 id="hero-title">Retail essentials, curated for the city pace.</h1>
          <p class="lead">
            Discover elevated basics, limited-run deals, and editorial picks built for everyday wear, thoughtful gifting, and a sharper home.
          </p>
          <div class="hero-actions">
            <a class="button button--primary" href="#featured-products">Shop featured</a>
            <a class="button button--secondary" href="#deals">View deals</a>
          </div>
        </div>

        <section class="hero-panel" aria-labelledby="spotlight-heading">
          <h2 id="spotlight-heading" class="sr-only">Spotlight</h2>
          <figure class="hero-panel__figure">
            <svg viewBox="0 0 640 420" role="img" aria-label="Editorial still life of wardrobe staples and a ceramic mug">
              <defs>
                <linearGradient id="bg" x1="0" x2="1" y1="0" y2="1">
                  <stop offset="0%" stop-color="#18304d" />
                  <stop offset="100%" stop-color="#09111b" />
                </linearGradient>
                <linearGradient id="glow" x1="0" x2="1">
                  <stop offset="0%" stop-color="#7fd1ff" />
                  <stop offset="100%" stop-color="#f7bc73" />
                </linearGradient>
              </defs>
              <rect width="640" height="420" rx="32" fill="url(#bg)"/>
              <circle cx="132" cy="86" r="62" fill="rgba(127, 209, 255, 0.14)"/>
              <circle cx="535" cy="118" r="94" fill="rgba(247, 188, 115, 0.1)"/>
              <rect x="105" y="146" width="154" height="178" rx="22" fill="#132237" stroke="rgba(255,255,255,0.15)"/>
              <rect x="284" y="96" width="170" height="234" rx="28" fill="#253b58" stroke="rgba(255,255,255,0.16)"/>
              <rect x="474" y="168" width="104" height="126" rx="22" fill="#9db5cc" opacity="0.9"/>
              <path d="M318 164h110l-14 120H330l-12-120Z" fill="url(#glow)" opacity="0.85"/>
              <path d="M143 184h82l10 114h-98l6-114Z" fill="#e4e8ef" opacity="0.8"/>
              <circle cx="535" cy="252" r="12" fill="#081018"/>
            </svg>
          </figure>
          <div class="hero-panel__meta">
            <div class="kicker-row">
              <span class="chip">Free shipping over $75</span>
              <span class="chip">Fresh drops every Thursday</span>
            </div>
            <p class="muted">Limited stock, fast checkout, and editorial picks sourced for comfort, utility, and style.</p>
          </div>
        </section>
      </section>

      <section class="section-card" id="featured-products" aria-labelledby="featured-heading">
        <div class="section-header">
          <div>
            <p class="eyebrow">Featured products</p>
            <h2 id="featured-heading">Best sellers worth a closer look</h2>
            <p>Filter by category to browse the collection. Each card keeps shopping actions separate and keyboard-friendly.</p>
          </div>
          <div class="section-actions" role="group" aria-label="Product filters">
            <button class="filter-button" type="button" aria-pressed="true" data-filter="all">All</button>
            <button class="filter-button" type="button" aria-pressed="false" data-filter="apparel">Apparel</button>
            <button class="filter-button" type="button" aria-pressed="false" data-filter="home">Home</button>
            <button class="filter-button" type="button" aria-pressed="false" data-filter="beauty">Beauty</button>
          </div>
        </div>

        <p class="status" id="filter-status" aria-live="polite">Showing all featured products.</p>

        <div class="grid products" id="product-grid">
          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <svg viewBox="0 0 480 320" role="img" aria-label="Sand-colored linen overshirt">
                <rect width="480" height="320" rx="24" fill="#122133"/>
                <rect x="126" y="56" width="228" height="188" rx="34" fill="#d6c19e"/>
                <path d="M185 58h110l-20 76h-70l-20-76Z" fill="#b89262"/>
                <path d="M170 88h140l26 160H144l26-160Z" fill="#e2d3b4" opacity="0.95"/>
                <rect x="228" y="112" width="24" height="110" rx="10" fill="#a67f4d"/>
              </svg>
            </div>
            <div class="product-body">
              <div>
                <div class="product-meta">
                  <span class="deal-badge">Bestseller</span>
                  <span class="rating" aria-label="Rated 4.8 out of 5">★★★★☆</span>
                </div>
                <h3>Linen overshirt</h3>
                <p class="muted">Breathable layering piece with a softened finish and a relaxed, tailored silhouette.</p>
              </div>
              <div class="product-meta">
                <span class="price">$88</span>
                <span class="compare">$110</span>
              </div>
              <button class="add-button" type="button" data-product-name="Linen overshirt" aria-label="Add to cart: Linen overshirt">Add to cart</button>
            </div>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-media">
              <svg viewBox="0 0 480 320" role="img" aria-label="Charcoal ceramic lamp">
                <rect width="480" height="320" rx="24" fill="#0f1a2a"/>
                <ellipse cx="240" cy="244" rx="112" ry="24" fill="rgba(127,209,255,0.09)"/>
                <rect x="210" y="92" width="60" height="108" rx="28" fill="#e6e9f1"/>
                <rect x="174" y="186" width="132" height="18" rx="9" fill="#48586d"/>
                <rect x="154" y="204" width="172" height="34" rx="16" fill="#172334"/>
                <rect x="182" y="240" width="116" height="18" rx="9" fill="#8796a8"/>
              </svg>
            </div>
            <div class="product-body">
              <div>
                <div class="product-meta">
                  <span class="deal-badge">New</span>
                  <span class="rating" aria-label="Rated 4.7 out of 5">★★★★☆</span>
                </div>
                <h3>Ceramic table lamp</h3>
                <p class="muted">Warm ambient light with a matte base and fabric shade for living spaces and desks.</p>
              </div>
              <div class="product-meta">
                <span class="price">$64</span>
              </div>
              <button class="add-button" type="button" data-product-name="Ceramic table lamp" aria-label="Add to cart: Ceramic table lamp">Add to cart</button>
            </div>
          </article>

          <article class="product-card" data-category="beauty">
            <div class="product-media">
              <svg viewBox="0 0 480 320" role="img" aria-label="Amber glass fragrance set">
                <rect width="480" height="320" rx="24" fill="#101824"/>
                <rect x="145" y="94" width="72" height="144" rx="26" fill="#e7b96f"/>
                <rect x="242" y="68" width="92" height="170" rx="30" fill="#9ec0d9"/>
                <rect x="165" y="72" width="32" height="28" rx="10" fill="#f6e5c7"/>
                <rect x="270" y="42" width="36" height="24" rx="8" fill="#f6e5c7"/>
                <path d="M145 220h72l14 30h-100l14-30Z" fill="#6e4b23"/>
                <path d="M242 214h92l18 38H224l18-38Z" fill="#305e7d"/>
              </svg>
            </div>
            <div class="product-body">
              <div>
                <div class="product-meta">
                  <span class="deal-badge">Top rated</span>
                  <span class="rating" aria-label="Rated 4.9 out of 5">★★★★★</span>
                </div>
                <h3>Fragrance duo</h3>
                <p class="muted">A citrus-forward scent and a deeper wood blend packaged for gifting.</p>
              </div>
              <div class="product-meta">
                <span class="price">$52</span>
              </div>
              <button class="add-button" type="button" data-product-name="Fragrance duo" aria-label="Add to cart: Fragrance duo">Add to cart</button>
            </div>
          </article>

          <article class="product-card" data-category="apparel">
            <div class="product-media">
              <svg viewBox="0 0 480 320" role="img" aria-label="Black commuter sneaker">
                <rect width="480" height="320" rx="24" fill="#0d141e"/>
                <path d="M110 198c30-14 88-18 136-14 34 2 62 14 96 16 28 2 54-4 80-8l22 56H98l12-50Z" fill="#9db2c8" opacity="0.14"/>
                <path d="M126 184c22-28 72-56 144-56 38 0 70 10 102 26 38 18 62 44 74 70H118l8-40Z" fill="#e9edf4"/>
                <rect x="186" y="108" width="130" height="66" rx="20" fill="#1f2937"/>
                <path d="M208 124h88l-12 24h-64l-12-24Z" fill="#8794a5"/>
              </svg>
            </div>
            <div class="product-body">
              <div>
                <div class="product-meta">
                  <span class="deal-badge">Editor pick</span>
                  <span class="rating" aria-label="Rated 4.8 out of 5">★★★★☆</span>
                </div>
                <h3>Commuter sneaker</h3>
                <p class="muted">Lightweight support, all-day comfort, and a low-profile shape that travels well.</p>
              </div>
              <div class="product-meta">
                <span class="price">$96</span>
              </div>
              <button class="add-button" type="button" data-product-name="Commuter sneaker" aria-label="Add to cart: Commuter sneaker">Add to cart</button>
            </div>
