      </section>

      <section class="section-card" id="deals" aria-labelledby="deals-heading">
        <div class="section-header">
          <div>
            <p class="eyebrow">Deals</p>
            <h2 id="deals-heading">Limited-time offers</h2>
            <p>Seasonal markdowns, bundle savings, and a few strategic splurges.</p>
          </div>
          <a class="button button--secondary" href="#featured-products">Shop all products</a>
        </div>

        <div class="grid deals">
          <article class="deal-card">
            <div class="deal-body">
              <span class="deal-badge">25% off</span>
              <h3>Home refresh bundle</h3>
              <p class="muted">Lamp, throw, and candle trio paired for a quiet living room update.</p>
              <div class="product-meta">
                <span class="price">$138</span>
                <span class="compare">$184</span>
              </div>
              <a class="story-link" href="#editorial">Explore styling notes</a>
            </div>
          </article>

          <article class="deal-card">
            <div class="deal-body">
              <span class="deal-badge">2 for $40</span>
              <h3>Fragrance refill pair</h3>
              <p class="muted">Keep your favorite scent on hand with a value pack for home and travel.</p>
